package com.renthouse.tenant;
import com.renthouse.auth.*;import com.renthouse.common.api.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/tenant")public class TenantController{private final com.renthouse.tenant.service.TenantService s;public TenantController(com.renthouse.tenant.service.TenantService s){this.s=s;}@GetMapping("/home")public ApiResponse<Home>home(){return ApiResponse.ok(s.getHomeData());}@GetMapping("/profile")public ApiResponse<Profile>profile(){CurrentUser.requireRole(UserRole.TENANT);long id=CurrentUser.require().id();var p=s.getProfileData(id);if(p==null)throw new com.renthouse.common.exception.BusinessException("USER_NOT_FOUND","用户不存在",org.springframework.http.HttpStatus.NOT_FOUND);return ApiResponse.ok(p);}
 public record Special(String id,String title,int rentCent){}public record Home(java.util.List<Special>specials,java.util.Map<String,Long>stats){}public record Profile(String nickname,String avatarUrl,String mobile,long favorites,long histories){}}
